    bars = []
    for r, row in enumerate(grid):
        vals = {v for v in row if v != 0}
        if len(vals) == 1 and all(v != 0 for v in row):
            bars.append((r, next(iter(vals))))
    if bars:
        period = len(bars)
        seq = {r % period: color for r, color in bars}
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal tracks share the invariant d = column - row. Their distinct
    # tracks define one cycle of colors, repeated across the whole grid.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in tracks and tracks[d] != color:
                    raise ValueError("inconsistent diagonal track")
                tracks[d] = color
    period = len(tracks)
    seq = {d % period: color for d, color in tracks.items()}
    return [[seq[(c - r) % period] for c in range(w)] for r in range(h)]
