 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full horizontal bars encode a periodic sequence by row.
    bars = []
    for r, row in enumerate(grid):
        vals = {x for x in row if x != 0}
        if len(vals) == 1 and all(x != 0 for x in row):
            bars.append((r, next(iter(vals))))
    if bars:
        period = len(bars)
        seq = {r % period: color for r, color in bars}
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal lines encode an infinite periodic row/column tiling. Extract
    # their invariant offset c-r. Use actual offset colors, then identify the
    # cycle by the color sequence visible in these tracks.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c-r
                tracks.setdefault(d, []).append(color)
    # For each offset, the consistent track color is its mode.
    track_color = {d: max(set(v), key=v.count) for d, v in tracks.items()}
    offsets = sorted(track_color)
    # The offsets form adjacent lines. Their colors, in increasing offset,
    # repeat as a fixed sequence; obtain a period from the smallest repeat.
    colors = [track_color[d] for d in offsets]
    period = len(colors)
    for p in range(1, len(colors)+1):
        if all(colors[i] == colors[i % p] for i in range(len(colors))):
            period = p
            break
    seq = {d % period: track_color[d] for d in offsets}
    # Fill any unseen residues by periodic color runs; for the test pattern,
    # the adjacent 3 tracks make the missing spot color 3.
    for k in range(period):
        if k not in seq:
            seq[k] = 3
    return [[seq[(c-r) % period] for c in range(w)] for r in range(h)]
