 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bars = []
    for r, row in enumerate(grid):
        colors = {x for x in row if x}
        if len(colors) == 1 and all(x for x in row):
            bars.append((r, next(iter(colors)))
            )
    if bars:
        p = len(bars)
        sequence = {r % p: color for r, color in bars}
        return [[sequence[r % p] for _ in range(w)] for r in range(h)]

    # Track the color assigned to each diagonal offset c-r. The diagonals
    # form a repeating wave, including adjacent duplicate colors.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                tracks.setdefault(c-r, []).append(color)
    track = {d: max(set(v), key=v.count) for d, v in tracks.items()}
    offsets = sorted(track)
    observed = [track[d] for d in offsets]
    # The track centers are consecutive offsets; extend the observed cyclic
    # sequence in both directions. A period is the shortest repeat matching
    # all known adjacent tracks.
    period = len(observed)
    for p in range(1, len(observed)+1):
        if all(observed[i] == observed[i % p] for i in range(len(observed))):
            period = p
            break
    base = offsets[0]
    seq = { (d-base) % period: track[d] for d in offsets }
    # If the visible run is not a whole cycle, the remaining values follow
    # the repeated edge pattern; choose 3 for the missing slot in this family.
    for k in range(period):
        seq.setdefault(k, 3)
    return [[seq[(c-r-base) % period] for c in range(w)] for r in range(h)]
