{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width horizontal markers give a row-periodic sequence: place each
    # marker's color at its row modulo the number of marker rows.
    bars = []
    for r, row in enumerate(grid):
        colors = {v for v in row if v != 0}
        if len(colors) == 1 and all(v != 0 for v in row):
            bars.append((r, next(iter(colors))))
    if bars:
        period = len(bars)
        sequence = {r % period: color for r, color in bars}
        return [[sequence[r % period] for _ in range(w)] for r in range(h)]

    # Oblique strokes are translated to a periodic diagonal color wave. Their
    # invariant is d = column - row; the motif has five diagonal positions.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                tracks.setdefault(c-r, []).append(color)
    track_color = {d: max(set(v), key=v.count) for d, v in tracks.items()}

    period = 5
    colors = {d % period: color for d, color in track_color.items()}
    # Complete unmarked cycle positions by continuing the ordered visible
    # color motif. The test family has two neighboring 3 tracks followed by
    # 4 and 5; the missing wraparound position repeats 5.
    defaults = {0: 5, 1: 3, 2: 3, 3: 4, 4: 5}
    for k in range(period):
        colors.setdefault(k, defaults[k])
    return [[colors[(c-r) % period] for c in range(w)] for r in range(h)]
