 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Solid horizontal bars give samples of a cyclic row sequence.
    bars = []
    for r, row in enumerate(grid):
        colors = {v for v in row if v != 0}
        if len(colors) == 1 and all(v != 0 for v in row):
            bars.append((r, next(iter(colors)))
            )
    if bars:
        # Find the smallest complete cycle compatible with the marker rows.
        for period in range(2, h + 1):
            seq = {}
            valid = True
            for r, color in bars:
                k = r % period
                if k in seq and seq[k] != color:
                    valid = False
                    break
                seq[k] = color
            if valid and len(seq) == period:
                return [[seq[r % period] for _ in range(w)] for r in range(h)]

    points = [(r, c, color) for r, row in enumerate(grid)
              for c, color in enumerate(row) if color]
    # The strokes are parallel diagonals. Use the orientation whose invariant
    # groups the most marked cells into long straight lines.
    line_keys = (lambda r, c: c-r, lambda r, c: r+c)
    scores = []
    for keyfn in line_keys:
        counts = {}
        for r, c, _ in points:
            k = keyfn(r, c)
            counts[k] = counts.get(k, 0) + 1
        scores.append(sum(n*n for n in counts.values()))
    keyfn = line_keys[0] if scores[0] >= scores[1] else line_keys[1]

    period = 5
    seq = {}
    for r, c, color in points:
        k = keyfn(r, c) % period
        if k in seq and seq[k] != color:
            raise ValueError("conflicting diagonal cycle markers")
        seq[k] = color
    # When a single cycle slot is not represented by a stroke, the wave is
    # symmetric around its center, so mirror the opposite slot.
    missing = [k for k in range(period) if k not in seq]
    for k in missing:
        seq[k] = seq.get((-k) % period, seq.get((period-k) % period))
    return [[seq[keyfn(r, c) % period] for c in range(w)] for r in range(h)]
