 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                tracks.setdefault(c - r, []).append(color)

    # Each distinct parallel diagonal stroke supplies one phase of the cycle.
    # The diagonal invariant is c-r for strokes running down-right.
    period = len(tracks)
    if period == 0:
        return [row[:] for row in grid]

    palette = {}
    for offset, values in tracks.items():
        # A stroke is a single color; mode is robust to any crossing cells.
        palette[offset % period] = max(set(values), key=values.count)

    return [[palette[(c-r) % period] for c in range(w)] for r in range(h)]
