 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Trace colors along lines of constant c-r, then repeat their sequence.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                tracks.setdefault(c-r, []).append(color)
    offsets = sorted(tracks)
    period = len(offsets)
    seq = [max(set(tracks[d]), key=tracks[d].count) for d in offsets]
    # Fill the grid with the repeated diagonal motif, anchored at the smallest
    # observed offset.
    anchor = offsets[0]
    return [[seq[(c-r-anchor) % period] for c in range(w)] for r in range(h)]
